GimCorpus.put(124,0,[[1,2,"וּקְרָא עָלֶיהָ. אֶת קְרִיאָתִי:",1,0],[1,3,"לִבְרֹחַ תַּרְשִׁישָׁה. יָם שֶׁשְּׁמוֹ תַּרְשִׁישׁ, וְהוּא בְּחוּצָה לָאָרֶץ. אָמַר: אֶבְרַח לִי הַיָּם, שֶׁאֵין הַשְּׁכִינָה שׁוֹרָה בְּחוּץ לָאָרֶץ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: חַיֶּיךָ, יֵשׁ לִי שְׁלוּחִים כְּיוֹצֵא בְּךָ לִשְׁלוֹחַ אַחֲרֶיךָ וּלְהָבִיאֲךָ מִשָּׁם. מָשָׁל לְעֶבֶד כֹּהֵן שֶׁבָּרַח מִן רַבּוֹ וְנִכְנַס לְבֵית הַקְּבָרוֹת. אָמַר לוֹ רַבּוֹ: יֵשׁ לִי עֲבָדִים כַּיוֹצֵא בְּךָ לִשְׁלוֹחַ אַחֲרֶיךָ וּלְהָבִיאֲךָ מִשָּׁם. וּמָה רָאָה יוֹנָה שֶׁלֹּא רָצָה לֵילֵךְ אֶל נִינְוֵה? אָמַר: הָעַכּוּ״ם קְרוֹבֵי תְשׁוּבָה הֵם, אִם אוֹמַר לָהֶם וְיַעֲשׂוּ תְשׁוּבָה נִמְצֵאתִי מְחַיֵּב אֶת יִשְׂרָאֵל שֶׁאֵין שׁוֹמְעִים לְדִבְרֵי הַנְּבִיאִים:",1,0],[1,3,"וַיִּתֵּן שְׂכָרָהּ. הִקְדִּים לָתֵת שְׂכָרָהּ, וְאֵין דֶּרֶךְ יוֹרְדֵי הַיָּם לָתֵת שְׂכַר הַסְּפִינָה עַד שְׁעַת הַיְּצִיאָה, וְהוּא הִקְדִּים. וְלֹא עוֹד אֶלָּא שֶׁנָּתַן שְׂכַר כֻּלָּהּ:",2,0],[1,4,"חִשְּׁבָה לְהִשָּׁבֵר. נִדְמֵית כְּאִלּוּ הִיא נִשְׁבֶּרֶת:",1,0],[1,5,"הַמַּלָּחִים. בְּנֵי אָדָם הַמַּנְהִיגִים אֶת הַסְּפִינָה:",1,0],[1,5,"אִישׁ אֶל אֱלֹהָיו. מִן שִׁבְעִים אוּמּוֹת שֶׁל עַכּוּ״ם הָיוּ שָׁם:",2,0],[1,6,"רַב הַחֹבֵל. שַׂר הַמַּלָּחִים, שֶׁאַף הֵם נִקְרָאִים חוֹבְלֵי הַיָּם, וּבְלַעַ״ז גובירניי״ל:",1,0],[1,6,"מַה לְּךָ נִרְדָּם. מַה לְּךָ לִהְיוֹת נִרְדָּם? אֵין עַתָּה עֵת רְדֹם:",2,0],[1,6,"יִתְעַשֵּׁת. לְשׁוֹן מַחֲשָׁבָה, וְכֵן ״עֶשְׁתֹּנֹתָיו״ (תהלים קמ״ו:ד), ״וּמַלְכָּא עֲשִׁית״ (דניאל ו:ד):",3,0],[1,7,"לְכוּ וְנַפִּילָה גוֹרָלוֹת. רוֹאִים הָיוּ שְׁאָר סְפִינוֹת הוֹלְכוֹת בַּיָּם בְּשָׁלוֹם וְשֶׁלָּהֶם מִשְׁתַּבֶּרֶת. אָמְרוּ: בִּשְׁבִיל אֶחָד מִמֶּנּוּ הוּא. כֵּן מָצִינוּ בְּפִרְקֵי דְרַבִּי אֱלִיעֶזֶר:",1,0],[1,7,"בְּשֶׁלְּמִי. בְּמַעֲשָׂיו שֶׁל מִי מִמֶּנּוּ:",2,0],[1,8,"הַגִּידָה נָּא לָנוּ בַּאֲשֶׁר לְמִי. לְמִי חָטָאתָ אֲשֶׁר בִּשְׁבִיל כֵּן הָרָעָה הַזֹּאת לָנוּ:",1,0],[1,8,"מַה מְּלַאכְתְּךָ. שֶׁמָּא פָּשַׁעְתָּ בְּאוּמָּנוּתְךָ:",2,0],[1,8,"וּמֵאַיִן תָּבֹא. שֶׁמָּא עַל אַנְשֵׁי אוֹתוֹ מָקוֹם נִגְזְרָה גְזֵרָה אֲפִילּוּ אֵין אַתָּה בָהּ:",3,0],[1,8,"וְאֵי מִזֶּה עַם אָתָּה. שֶׁמָּא עַמְּךָ חָטְאוּ:",4,0],[1,10,"מַה זֹּאת עָשִׂיתָ. לָמָּה עָשִׂיתָ כֵּן לִבְרֹחַ מִן מוֹשֵׁל כָּזֶה:",1,0],[1,13,"וַיַּחְתְּרוּ הָאֲנָשִׁים. יָגְעוּ וְעָסְקוּ כְּחוֹתֵר בַּמַּחְתֶּרֶת:",1,0],[1,14,"בְּנֶפֶשׁ הָאִישׁ הַזֶּה. בֶּעָוֹן שֶׁנִּשְׁלַח יָד בְּנַפְשׁוֹ:",1,0],[1,16,"וַיִּדְּרוּ נְדָרִים. שֶׁיִּתְגַּיְּרוּ:",1,0],[2,1,"דָּג גָּדוֹל. זָכָר הָיָה וְהָיָה עוֹמֵד בְּרֶוַח וְלֹא נָתַן לֵב לְהִתְפַּלֵּל. רָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַדָּג וְהֵקִיאוֹ לְתוֹךְ פִּיהָ שֶׁל נְקֵבָה שֶׁהָיְתָה מְלֵאָה עוּבָּרִים, וְהָיָה שָׁם בְּדוֹחַק וַיִּתְפַּלֵּל שָׁם, שֶׁנֶּאֱמַר ״מִמְּעֵי הַדָּגָה״. (וַיְמַן ה׳. אוֹתָן ט״ז יָמִים שֶׁחָסְרוּ יִשְׂרָאֵל מִן הַמָּן, שֶׁלֹּא אָכְלוּ מ׳ שָׁנִים שְׁלֵימוֹת הַמָּן. זֶה לָקַח הַקָּבָּ״ה וּפִרְנֵס אֶת הַדָּג שֶׁלֹּא יְעוּכַּל יוֹנָה בְּמֵעָיו, וְגַם יוֹנָה אָכַל בְּתוֹכוֹ מִזֶּה הַמָּן. לָכֵן נֶאֱמַר וַיְמַן – אוֹתִיּוֹת י״ו מ״ן. וְכֵן וַיְמַ״ן קִיקָיוֹן שֶׁהָיָה אוֹכֵל ד׳ עוֹמְרִים, לָכֵן נֶאֱמַר ד׳ פְּעָמִים וַיְמַן. וּבְלָשׁוֹן יָוָן נִקְרָא מָן קִיקָא, וְעַל זֶה נֶאֱמַר קִי״ק יוֹ״ן. סוד מישרים):",1,0],[2,2,"(ה׳ אלהיו שִׁתֵּף דִּין וְרַחֲמִים, זְכוּת אַבְרָהָם וְיִצְחָק. ממעי הדגה זֶה יַעֲקֹב. סוד מישרים):",1,0],[2,3,"מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי. מִבֶּטֶן הַדָּג שֶׁהוּא כִּשְׁאוֹל לִי:",1,0],[2,4,"כָּל מִשְׁבָּרֶיךָ וְגַלֶּיךָ. כָּל נַחְשׁוּלוֹהִי דְיַמָּא, עַל שֵׁם שֶׁהַנַּחְשׁוֹל מְשַׁבֵּר וּמְפָרֵק אֶת הַיָּם:",1,0],[2,5,"וַאֲנִי אָמַרְתִּי. כְּשֶׁהִשְׁלִיכוּנִי אֶל הַיָּם: הִנְנִי מֵת וְנִגְרַשְׁתִּי מִנֶּגֶד עֵינֶיךָ:",1,0],[2,5,"אַךְ. רָאִיתִי שֶׁקִּיַּמְתַּנִי כָּל אֵלּוּ הַיָּמִים, יָדַעְתִּי כִּי אוֹסִיף לְהַבִּיט אֶל הֵיכַל קָדְשֶׁךָ:",2,0],[2,6,"סוּף חָבוּשׁ לְרֹאשִׁי. יַמָּא דְסוּף תָּלֵי לְעֵיל מִן רֵישִׁי, שֶׁהֶרְאָהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא יַם סוּף וְאֵיךְ עָבְרוּ יִשְׂרָאֵל בְּתוֹכוֹ, שֶׁהָיוּ שְׁתֵּי עֵינֵי הַדָּגָה כְּמִין שְׁתֵּי חַלּוֹנוֹת וּמִסְתַּכֵּל וְרוֹאֶה כָּל מַה שֶּׁבַּיָּם:",1,0],[2,7,"לְקִצְבֵי הָרִים יָרַדְתִּי. לְסוֹף מִדַּת הֶהָרִים הַקְּבוּעִים עַל הַתְּהוֹם יָרַדְתִּי:",1,0],[2,7,"״אֲנִי אָמַרְתִּי״ הָאָרֶץ בְּרִיחֶיהָ בַעֲדִי. כְּנֶגְדִּי לְמַעְלָה מִמֶּנִּי סָגוּר וְלֹא אֵצֵא לְעוֹלָם. בַּעֲדִי כְּמוֹ ״וְסָגַרְתְּ הַדֶּלֶת בַּעֲדֵךְ״ (מלכים ב ד:ד), וְכֵן כָּל בְּעַד שֶׁבַּמִּקְרָא ״עוֹר בְּעַד עוֹר״ (איוב ב:ד) – אֵבֶר כְּנֶגֶד אֵבֶר:",2,0],[2,7,"לְעוֹלָם. מוּסָב עַל מַה שֶּׁאָמַר לְמַעְלָה: וַאֲנִי אָמַרְתִּי נִגְרַשְׁתִּי, וַאֲנִי אָמַרְתִּי הָאָרֶץ בְּרִיחֶיהָ סְגוּרִים בַּעֲדִי לְעוֹלָם:",3,0],[2,7,"וַתַּעַל מִשַּׁחַת חַיַּי. אֲבָל כְּבָר רָאִיתִי כָּאן גֵּיהִנֹּם וּמִשָּׁם הֶעֱלִיתָנִי, וְהִנְנִי עַתָּה כְּנֶגֶד תַּחַת הַהֵיכָל שֶׁבִּירוּשָׁלַיִם, כְּעִנְיָן שֶׁנֶּאֱמַר: ״אַךְ אוֹסִיף לְהַבִּיט אֶל הֵיכַל קָדְשֶׁךָ״, ״וַתָּבֹא אֵלֶיךָ תְפִלָּתִי אֶל הֵיכַל קָדְשֶׁךָ״:",4,0],[2,8,"בְּהִתְעַטֵּף. בְּאִשְׁתַּלְהָיוּת, וְכֵן ״בְּהִתְעַטֵּף נַפְשָׁם״, וְכֵן ״בַּעֲטֹף עוֹלֵל״ (איכה ב:יא):",1,0],[2,9,"מְשַׁמְּרִים הַבְלֵי שָׁוְא. אוֹתָן שֶׁעוֹבְדִים לְעַכּוּ״ם:",1,0],[2,9,"חַסְדָּם יַעֲזֹבוּ. יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכָּל חַסְדָּם וְטוֹבָתָם מֵאִתּוֹ יַעֲזֹבוּ, אֲבָל אֲנִי אֵינִי כֵן אֶלָּא בְּקוֹל תּוֹדָה אֶזְבְּחָה לָּךְ. כָּךְ תִּרְגֵּם יוֹנָתָן. וּפִרְקֵי דְרַבִּי אֱלִיעֶזֶר דָּרְשׁוּ כְּלַפֵּי הַמַּלָּחִים שֶׁעָזְבוּ חַסְדָּם שֶׁהָיוּ מְטִיבִים לְעַכּוּ״ם וְנִתְגַּיְּרוּ:",2,0],[2,10,"יְשׁוּעָתָה לַה׳. נִדְרֵי שְׁלָמִים וְתוֹדָה אֲשַׁלֵּם לְשֵׁם יְשׁוּעוֹת אֲשֶׁר לַה׳. יְשׁוּעָתָה כְּמוֹ לִישׁוּעָתָה, וְכֵן ״קוּמָה עֶזְרָתָה לָּנוּ״ (תהלים מד:כז) – לְעֶזְרָה שֶׁלָּנוּ:",1,0],[3,4,"נֶהְפָּכֶת. נֶחֱרֶבֶת. (וְלֹא אָמַר נֶחֱרֶבֶת כִּי נֶהְפָּכֶת מְשַׁמֵּשׁ שְׁתֵּי לְשׁוֹנוֹת, רַע וְטוֹב: אִם לֹא יַעֲשׂוּ תְשׁוּבָה – נֶחֱרֶבֶת, וְאִם יַעֲשׂוּ תְשׁוּבָה – אָז נֶהְפָּכֶת. עַל אַנְשֵׁי נִינְוֵה קָאֵי שֶׁיַּהַפְכוּ מֵרָעָה לְטוֹבָה וְיַעֲשׂוּ תְשׁוּבָה. הג״ה דר״ע):",1,0],[3,6,"אַדַּרְתּוֹ. לְבוּשׁ יְקָרֵיהּ:",1,0],[3,7,"וַיַּזְעֵק. צִוָּה וְהִכְרִיז:",1,0],[3,7,"מִטַּעַם הַמֶּלֶךְ וּגְדוֹלָיו. מֵעֲצַת הַמֶּלֶךְ וּגְדוֹלָיו צִוּוּ לְהַכְרִיז:",2,0],[3,8,"וְיִקְרְאוּ אֶל אֱלֹהִים בְּחָזְקָה. אָסְרוּ אִמָּהוֹת לְבַד וְהַוְּלָדוֹת לְבַד. אָמְרוּ לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם, אִם אֵין אַתָּה מְרַחֵם עָלֵינוּ אֵין אָנוּ מְרַחֲמִים עַל אֵלּוּ:",1,0],[3,9,"מִי יוֹדֵעַ. עֲבֵירוֹת שֶׁבְּיָדוֹ יָשׁוּב:",1,0],[3,10,"וַיִּנָּחֶם הָאֱלֹהִים. נִתְעַשֵּׁת עַל הָרָעָה לָשׁוּב מִמֶּנָּה:",1,0],[4,1,"וַיֵּרַע אֶל יוֹנָה. אָמַר: עַכְשָׁיו יֹאמְרוּ הָעַכּוּ״ם שֶׁאֲנִי נְבִיא הַשֶּׁקֶר:",1,0],[4,2,"הֲלֹא זֶה דְבָרִי. יוֹדֵעַ אֲנִי שֶׁאִם יַחְזְרוּ בִּתְשׁוּבָה לֹא תַּחֲרִיבֵם וְאֶהְיֶה שַׁקְרָן בְּעֵינֵיהֶם:",1,0],[4,6,"וַיְמַן. לְשׁוֹן הַזְמָנָה:",1,0],[4,6,"לְהַצִּיל לוֹ מֵרָעָתוֹ. מֵחוֹם הַשֶּׁמֶשׁ:",2,0],[4,6,"קִיקָיוֹן. עֵשֶׂב הַגָּדֵל לְמַעְלָה בַּעֲנָפִים רַבִּים וּמֵצִיל, וְכָךְ שְׁמוֹ:",3,0],[4,7,"וַתַּךְ. הַתּוֹלַעַת אֶת הַקִּיקָיוֹן. בִּמְקוֹם שֶׁיֹּאמַר לְזָכָר וַיַּךְ, יֹאמַר לְשׁוֹן נְקֵבָה וַתַּךְ:",1,0],[4,8,"חֲרִישִׁית. אָמְרוּ רַבּוֹתֵינוּ: בְּשָׁעָה שֶׁמְּנַשֶּׁבֶת מַשְׁתֶּקֶת כָּל הָרוּחוֹת מִפָּנֶיהָ וְהִיא חַמָּה מְאֹד. וְכֵן תִּרְגֵּם יוֹנָתָן: שְׁתִיקָא:",1,0],[4,8,"וַיִּתְעַלָּף. פשמיי״ר בְּלַעַ״ז:",2,0],[4,10,"לֹא עָמַלְתָּ בּוֹ. בַּחֲרִישָׁה וּזְרִיעָה וְהַשְׁקָאַת מַיִם:",1,0],[4,10,"שֶׁבִּן לַיְלָה. כְּמוֹ בֶּן לַיְלָה, לֹא גָדַל אֶלָּא לַיְלָה אֶחָד:",2,0],[4,11,"אֲשֶׁר לֹא יָדַע וגו׳. קְטַנִּים:",1,0],[4,11,"וּבְהֵמָה רַבָּה. בְּנֵי אָדָם גְּדוֹלִים וְדַעְתָּן כִּבְהֵמָה, שֶׁאֵינָם מַכִּירִים מִי בְּרָאָם:",2,0]]);
